pub fn contains(&self, ip: IpAddr) -> bool {
    let mut i = 0;
    while i < self.entries.len() {
        let (nw, prefix) = self.entries[i];
        if entry_contains(nw, prefix, ip) {
            return true;
        }
        i += 1;
    }
    false
